CREATE TABLE `notifications` (
  `id` int NOT NULL AUTO_INCREMENT,
  `message` text NOT NULL,
  `user_id` int DEFAULT NULL,
  `type` varchar(30) NOT NULL DEFAULT 'info',
  `incident_ref` varchar(20) DEFAULT NULL,
  `is_mention` tinyint(1) NOT NULL DEFAULT '0',
  `actor_id` int DEFAULT NULL,
  `mailbox_message_id` varchar(255) DEFAULT NULL,
  `is_read` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_notif_user` (`user_id`,`is_read`),
  KEY `idx_notif_incident` (`incident_ref`),
  KEY `idx_notif_created` (`user_id`,`id`),
  KEY `idx_notif_retention` (`created_at`),
  KEY `idx_notif_mailbox_message` (`mailbox_message_id`,`is_read`),
  CONSTRAINT `notifications_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=51718 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
