DROP TABLE IF EXISTS `operations_alert_comments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `operations_alert_comments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fingerprint_key` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `alert_fingerprint` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `comment_text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_resolution` tinyint(1) NOT NULL DEFAULT '0',
