--
-- Table structure for table `operations_email_incident_audit`
--

DROP TABLE IF EXISTS `operations_email_incident_audit`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `operations_email_incident_audit` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `graph_message_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email_subject` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_category` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `identified_customer_id` int DEFAULT NULL,
  `identified_customer_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jira_project_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `match_location` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `incident_id` int DEFAULT NULL,
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requested_by` int NOT NULL,
  `requested_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_operations_email_audit_message` (`graph_message_id`),
  KEY `idx_operations_email_audit_incident` (`incident_id`),
  KEY `operations_email_audit_customer_fk` (`identified_customer_id`),
  KEY `operations_email_audit_user_fk` (`requested_by`),
  CONSTRAINT `operations_email_audit_customer_fk` FOREIGN KEY (`identified_customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `operations_email_audit_incident_fk` FOREIGN KEY (`incident_id`) REFERENCES `incidents` (`id`) ON DELETE SET NULL,
  CONSTRAINT `operations_email_audit_user_fk` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=198 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

